// ===== Find Invoice PDFs =====
// Purpose: pick the best PDF from each mail's attachments.
// Result: json.hatPDF (true/false), json.dateiname, binary.attachment_0 (only the chosen PDF)

// --- Constants ---
// Filename words that suggest "not an invoice" (fallback exclusion)
const skipWords = /(widerruf|agb|storno|retoure|return|terms|datenschutz|hinweis|newsletter)/i;
// Filename words that suggest an invoice (take priority)
const invoiceWords = /(rechnung|invoice|beleg|quittung|bill|receipt)/i;

// --- 1. Collect all PDF attachments of the mail ---
// PDF = MIME type application/pdf OR file name ending in .pdf
const binary = $input.item.binary || {};
const pdfKeys = Object.keys(binary).filter(k => {
  const a = binary[k];
  return a.mimeType === 'application/pdf' || (a.fileName || '').toLowerCase().endsWith('.pdf');
});

// --- 2. Pick the best PDF ---
// First choice: file name contains an invoice word. Otherwise: first PDF without a skip word.
const key = pdfKeys.find(k => invoiceWords.test(binary[k].fileName || ''))
         || pdfKeys.find(k => !skipWords.test(binary[k].fileName || ''));

// --- 3a. No usable PDF: set the flags to "no" and clear the binary ---
if (!key) {
  $input.item.binary = {};
  $input.item.json.hatPDF = false;
  $input.item.json.dateiname = '';
  return $input.item;
}

// --- 3b. PDF found: pass it on as attachment_0 and set the flags ---
const fileName = binary[key].fileName || '';
$input.item.binary = { attachment_0: binary[key] };
$input.item.json.hatPDF = true;
$input.item.json.dateiname = fileName;
return $input.item;
